/* MIT. Repeatable source item-collection quests. No new quest/save system. */
static int core_quest_plain53(const OwnedItem52*p,unsigned source){return p->sourceID==source&&p->identified&&!p->equipped&&!p->refine&&!p->bound&&!(p->flags&~OWNED_LEGACY_STACK52)&&!(p->cards[0]|p->cards[1]|p->cards[2]|p->cards[3]);}
static unsigned core_quest_count53(const OwnedItems52*b,int item){unsigned source=itemDefs[item].id,total=0;for(unsigned i=0;i<b->count[0];i++)if(core_quest_plain53(b->items+i,source))total+=b->items[i].quantity;return total;}
static int core_quest_exchange53(Combat*g,unsigned index){if(index>=sizeof(coreQuests53)/sizeof(*coreQuests53)||g->hp<=0)return 0;const CoreQuest53*q=coreQuests53+index;if(g->zeny<(int)q->zeny){combat_notice(g,POP_ITEMS,"Need %u Zeny. Nothing spent.",q->zeny);return 0;}for(unsigned i=0;i<q->count;i++)if(core_quest_count53(&g->owned52,q->needs[i][0])<q->needs[i][1]){combat_notice(g,POP_ITEMS,"Need %u %s. Use plain, unequipped items.",q->needs[i][1],itemDefs[q->needs[i][0]].name);return 0;}
 OwnedItems52*trial=malloc(sizeof(*trial));if(!trial){combat_notice(g,POP_ITEMS,"Cannot prepare exchange. Nothing spent.");return 0;}*trial=g->owned52;
 for(unsigned i=0;i<q->count;i++){unsigned source=itemDefs[q->needs[i][0]].id,left=q->needs[i][1];while(left){OwnedItem52*p=NULL;for(unsigned j=0;j<trial->count[0];j++)if(core_quest_plain53(trial->items+j,source)){p=trial->items+j;break;}if(!p){free(trial);return 0;}unsigned amount=p->quantity<left?p->quantity:left;if(owned_remove52(trial,0,p->uid,amount)!=OWNED_OK52){free(trial);return 0;}left-=amount;}}
 int result=owned_add52(trial,0,itemDefs[q->reward].id,1,item_rule52);uint64_t weight=0;for(unsigned i=0;i<trial->count[0];i++){const OwnedItem52*p=trial->items+i;const OwnedRule52*r=item_rule52(p->sourceID);weight+=(uint64_t)r->weight*p->quantity;}
 if(result!=OWNED_OK52||weight>(uint64_t)inventory_weight_max(g)){free(trial);combat_notice(g,POP_ITEMS,"Make room for the reward. Materials and Zeny kept.");return 0;}g->owned52=*trial;free(trial);g->zeny-=q->zeny;combat_notice(g,POP_ITEMS,"Quest complete! Received %s.",itemDefs[q->reward].name);return 1;
}
